INSERT INTO riru.content(kind, data) VALUES ('strategic', $seed$[{"id": "Анализ потерь", "title": "Анализ потерь", "tasks": [{"id": "С-01", "title": "Годовой анализ уровня потерь по РЭС", "desc": "Формирование годового анализа уровня потерь по всем ТП и фидерам РЭС", "deadline": "Январь", "norm": "ПП РФ №861"}, {"id": "С-02", "title": "Анализ технических и коммерческих потерь", "desc": "Разделение потерь на технические и коммерческие, выявление причин отклонений", "deadline": "Январь", "norm": "ПП РФ №861"}, {"id": "С-03", "title": "Выявление объектов с риском НУП/БДП", "desc": "Выявление объектов с повышенным риском неучтённого и бездоговорного потребления", "deadline": "Январь", "norm": "ПП РФ №442"}, {"id": "С-11", "title": "Выгрузка очагов потерь ТП по фидерам", "desc": "Выгрузка очагов потерь ТП на основании анализа каждого фидера", "deadline": "Январь", "norm": "ПП РФ №861"}, {"id": "С-12", "title": "Анализ снижения потребления", "desc": "Выявление потребителей со снижением потребления", "deadline": "Январь", "norm": "ПП РФ №442"}]}, {"id": "Приборы учёта и АСКУЭ", "title": "Приборы учёта и АСКУЭ", "tasks": [{"id": "С-06", "title": "План замены ПУ и модемов АСКУЭ", "desc": "Формирование годового плана замены приборов учёта и модемов АСКУЭ", "deadline": "Январь", "norm": "ФЗ-522"}, {"id": "С-09", "title": "Планирование объёмов монтажа ПУ", "desc": "Планирование объёмов работ по монтажу ПУ на год", "deadline": "Январь", "norm": "ФЗ-522"}, {"id": "С-10", "title": "Определение потребности в ПУ", "desc": "Определение потребности в приборах учёта на предстоящий год", "deadline": "Январь", "norm": "ФЗ-522"}, {"id": "С-13", "title": "Выгрузка потребителей с истекающим МПИ", "desc": "Выгрузка потребителей с истекающим межповерочным интервалом помесячно", "deadline": "Январь", "norm": "ФЗ-102"}]}, {"id": "Планирование и KPI", "title": "Планирование и KPI", "tasks": [{"id": "С-04", "title": "План мероприятий по группе риска", "desc": "Формирование плана мероприятий по ра