INSERT INTO riru.content(kind, data) VALUES ('operational', $seed$[{"id": "Утро", "title": "Утро", "time": "07:30-10:00", "sections": [{"title": "Организация работы персонала", "resp": "", "items": [{"id": "О-01", "title": "Утренняя планерка", "desc": "Провести/проконтролировать утреннюю планерку", "req": true}, {"id": "О-02", "title": "Распределение по бригадам", "desc": "Контроль распределения персонала по бригадам", "req": true}, {"id": "О-03", "title": "Проверка СИЗ", "desc": "Контроль укомплектованности и исправности СИЗ", "req": true}, {"id": "О-04", "title": "Проверка инструмента", "desc": "Контроль наличия и исправности инструмента", "req": true}, {"id": "О-05", "title": "Пломбы и бланки", "desc": "Контроль наличия пломб и бланочной продукции", "req": true}, {"id": "О-06", "title": "Постановка задач персоналу", "desc": "Постановка первоочередных задач линейному персоналу", "req": true}, {"id": "О-07", "title": "Наряды-допуски", "desc": "Контроль оформления нарядов-допусков", "req": true}, {"id": "О-08", "title": "Целевые инструктажи", "desc": "Контроль проведения целевых инструктажей", "req": true}, {"id": "О-09", "title": "Выезд на объект", "desc": "Контроль выезда с электромонтерами", "req": true}]}, {"title": "Учёт и документооборот", "resp": "", "items": [{"id": "О-10", "title": "Внесение работ в 1С СУТЭ", "desc": "Контроль внесения работ за предыдущий день", "req": true}, {"id": "О-11", "title": "Реестры для ГП", "desc": "Контроль формирования реестров для ГП", "req": true}, {"id": "О-12", "title": "Проводка пломб в 1С", "desc": "Контроль проводки пломбировочного материала", "req": true}, {"id": "О-13", "title": "Документы по ТП", "desc": "Контроль подготовки документов по договорам ТП", "req": true}]}]}, {"id": "День", "title": "День", "time": "10:00-16:00", "sections": [{"title": "Контроль и мониторинг", "resp": "", "items": [{"id": "О-14", "title": "Задачи СЭДО", "desc": "Контроль выполнения задач через СЭДО", "req": true}, {"id": "О-15", "title": "Обращения потребителей", "desc": "Контроль работы с обращениями", "req": true}, {"id": "О-16", "title": "Мониторинг опроса АСКУЭ", "desc": "Контроль процента опроса ПУ", "req": true}, {"id": "О-17", "title": "Контроль бригад", "desc": "Контроль работы персонала на объектах", "req": true}, {"id": "О-18", "title": "Мониторинг договоров ТП", "desc": "Контроль реестра договоров ТП", "req": true}]}, {"title": "Аналитика и выгрузки", "resp": "", "items": [{"id": "О-19", "title": "Текущая отчетность", "desc": "Контроль подготовки отчетности", "req": true}, {"id": "О-20", "title": "Выгрузка списков АСКУЭ", "desc": "Контроль выгрузки списков для объезда", "req": false}, {"id": "О-21", "title": "Списки группы риска", "desc": "Контроль выгрузки потребителей группы риска", "req": false}, {"id": "О-22", "title": "Мгновенные значения Пирамида", "desc": "Контроль выгрузки мгновенных значений", "req": false}, {"id": "О-23", "title": "Список отключенных", "desc": "Контроль выгрузки списка отключенных потребителей", "req": false}, {"id": "О-24", "title": "Работа с потребителями", "desc": "Контроль приема потребителей", "req": false}]}, {"title": "Материально-техническое обеспечение", "resp": "", "items": [{"id": "О-25", "title": "Мониторинг АСКУЭ", "desc": "Контроль работоспособности АСКУЭ", "req": false}, {"id": "О-26", "title": "Выдача электросчетчиков", "desc": "Контроль выдачи электросчетчиков и материала", "req": true}, {"id": "О-27", "title": "Программирование ПУ", "desc": "Контроль программирования приборов учета", "req": false}]}]}, {"id": "Вечер", "title": "Вечер", "time": "16:00-17:30", "sections": [{"title": "Приёмка и завершение дня", "resp": "", "items": [{"id": "О-28", "title": "Приемка работ", "desc": "Контроль приемки выполненных работ", "req": true}, {"id": "О-29", "title": "Приемка документов", "desc": "Контроль приемки документов и материалов", "req": true}, {"id": "О-30", "title": "Внесение в журнал ПУ", "desc": "Контроль внесения информации в журнал ПУ", "req": true}, {"id": "О-31", "title": "Фотоотчеты", "desc": "Контроль сбора фотоотчетов", "req": true}, {"id": "О-32", "title": "Акты КСП и ПСУ в 1С", "desc": "Контроль занесения актов в 1С", "req": true}, {"id": "О-33", "title": "Акты НУП", "desc": "Контроль передачи актов НУП в течение 3 дней", "req": true}, {"id": "О-34", "title": "Передача остатков пломб", "desc": "Контроль приемки остатков пломбировочного материала", "req": true}, {"id": "О-35", "title": "Планирование на завтра", "desc": "Планирование работ на следующий день", "req": true}]}]}]$seed$::jsonb);
INSERT INTO riru.content(kind, data) VALUES ('techcards', $seed$[{"id": 1, "group": "install", "title": "Установка (замена) ПУ сплит-исполнения до 1000 В", "fullTitle": "Установка (замена) однофазного/трехфазного прибора учета электроэнергии прямого включения сплит-исполнения в электроустановках напряжением до 1000 В", "sections": [{"name": "Назначение", "text": "Работы предназначены для установки или замены однофазных и трехфазных приборов учета электроэнергии прямого включения в сплит-исполнении в электроустановках до 1000 В. Установка выполняется на опорах ВЛ-0,4 кВ или фасадах зданий."}, {"name": "Условия выполнения", "text": "Работы выполняются по наряду-допуску со снятием напряжения и заземлением участка. Вывод в ремонт линии осуществляет оперативный или оперативно-ремонтный персонал."}, {"name": "Подготовка", "text": "Оформление наряда-допуска, отключение линии, проверка отсутствия напряжения и установка заземлений. Бригада укомплектовывается прибором учета, монтажными материалами, пломбами, инструментом и СИЗ."}, {"name": "Выполнение", "text": "Демонтаж существующего ПУ, установка измерительного и интерфейсного модулей, механическое крепление, электрическое подключение фазных и нулевых проводников, контроль качества соединений."}, {"name": "Завершение", "text": "Пломбировка ПУ, восстановление электроснабжения, контрольный осмотр и оформление результатов."}]}, {"id": 2, "group": "install", "title": "Установка (замена) 1ф ПУ щитового исполнения до 1000 В", "fullTitle": "Установка (замена) однофазного прибора учета электроэнергии прямого включения щитового исполнения с вводным коммутационным аппаратом в электроустановках напряжением до 1000 В", "sections": [{"name": "Назначение", "text": "Работы предназначены для установки или замены однофазного прибора учета щитового исполнения с вводным коммутационным аппаратом в электроустановках до 1000 В."}, {"name": "Условия выполнения", "text": "Работы выполняются по распоряжению или в порядке текущей эксплуатации без подъема на высоту. Напряжение снимается вводным коммутационным аппаратом."}, {"name": "Подготовка", "text": "Оформление распоряжения или производственного задания. Проверка исправности вводного аппарата, наличие ПУ, инструмента, СИЗ и пломбировочных материалов."}, {"name": "Выполнение", "text": "Снятие напряжения вводным аппаратом, проверка отсутствия напряжения, демонтаж старого ПУ, установка нового, подключение проводников, проверка работоспособности."}, {"name": "Завершение", "text": "Пломбировка, включение вводного аппарата и оформление выполненных работ."}]}, {"id": 3, "group": "install", "title": "Установка (замена) 3ф ПУ щитового исполнения до 1000 В", "fullTitle": "Установка (замена) трехфазного прибора учета электроэнергии прямого включения щитового исполнения с вводным коммутационным аппаратом в электроустановках напряжением до 1000 В", "sections": [{"name": "Назначение", "text": "Работы предназначены для установки или замены трехфазных приборов учета прямого включения щитового исполнения в электроустановках до 1000 В."}, {"name": "Условия выполнения", "text": "Работы выполняются по распоряжению с обязательным снятием напряжения через вводное коммутационное устройство. Подъем на высоту не требуется."}, {"name": "Подготовка", "text": "Проверка оформления распоряжения, исправность вводного аппарата, комплектность ПУ и инструмента. Обеспечение доступа к месту установки."}, {"name": "Выполнение", "text": "Снятие напряжения, проверка его отсутствия, демонтаж существующего ПУ, установка нового трехфазного прибора, подключение фазных и нулевых цепей, проверка схемы."}, {"name": "Завершение", "text": "Пломбировка, восстановление электроснабжения и оформление документации."}]}, {"id": 4, "group": "install", "title": "Установка (замена) ПУ сплит-исполнения без спецтехники", "fullTitle": "Установка (замена) однофазного/трехфазного прибора учета электроэнергии прямого включения сплит-исполнения в электроустановках напряжением до 1000 В без применения спецтехники", "sections": [{"name": "Назначение", "text": "Работы предназначены для установки или замены приборов учета сплит-исполнения без использования подъемных механизмов, с выполнением подъема вручную."}, {"name": "Условия выполнения", "text": "Работы выполняются по наряду-допуску с отключением ВЛ и соблюдением требований работ на высоте. Перед подъемом оценивается состояние опоры."}, {"name": "Подготовка", "text": "Оформление наряда-допуска, отключение линии, проверка отсутствия напряжения и заземление. Проверка состояния опоры, комплектность оборудования и СИЗ."}, {"name": "Выполнение", "text": "Демонтаж старого оборудования, установка модулей ПУ, механическое крепление, электрическое подключение и контроль соединений."}, {"name": "Завершение", "text": "Пломбировка ПУ, ввод линии в работу, оформление результатов."}]}, {"id": 5, "group": "install", "title": "Установка (замена) 3ф ПУ полукосвенного включения", "fullTitle": "Установка (замена) трехфазного прибора учета электроэнергии полукосвенного включения щитового исполнения", "sections": [{"name": "Назначение", "text": "Работы предназначены для установки или замены трехфазных приборов учета полукосвенного включения с применением измерительных трансформаторов тока."}, {"name": "Условия выполнения", "text": "Работы выполняются по распоряжению со снятием напряжения через вводной аппарат. Подъем на высоту не требуется."}, {"name": "Подготовка", "text": "Оформление распоряжения, подготовка ПУ, трансформаторов тока, инструмента и средств защиты."}, {"name": "Выполнение", "text": "Снятие напряжения, демонтаж старого ПУ, установка трансформаторов тока, монтаж ПУ, подключение измерительных цепей, проверка схемы учета."}, {"name": "Завершение", "text": "Пломбировка и оформление выполненных работ."}]}, {"id": 6, "group": "install", "title": "Установка (замена) 3ф ПУ косвенного включения выше 1000 В", "fullTitle": "Установка (замена) трехфазного прибора учета электроэнергии косвенного включения щитового исполнения в электроустановках напряжением выше 1000 В", "sections": [{"name": "Назначение", "text": "Работы предназначены для установки или замены приборов учета косвенного включения в электроустановках напряжением выше 1000 В с использованием трансформаторов тока и напряжения."}, {"name": "Условия выполнения", "text": "Работы выполняются по наряду-допуску с обязательным отключением и заземлением электроустановки."}, {"name": "Подготовка", "text": "Оформление наряда-допуска, подготовка ПУ, трансформаторов, измерительных цепей, инструмента и СИЗ."}, {"name": "Выполнение", "text": "Демонтаж старого ПУ, установка нового, подключение цепей ТТ и ТН, проверка корректности учета."}, {"name": "Завершение", "text": "Контроль, оформление документации и ввод установки в работу."}]}, {"id": 7, "group": "install", "title": "Установка (замена) 3ф ПУ прямого включения 6(10) кВ", "fullTitle": "Установка (замена) трехфазного прибора учета электроэнергии прямого включения в электроустановках напряжением 6(10) кВ", "sections": [{"name": "Назначение", "text": "Работы предназначены для установки или замены приборов учета прямого включения в электроустановках 6(10) кВ."}, {"name": "Условия выполнения", "text": "Работы выполняются по наряду-допуску с полным отключением и заземлением электроустановки."}, {"name": "Подготовка", "text": "Оформление наряда-допуска, отключение и заземление, подготовка оборудования, инструмента и СИЗ."}, {"name": "Выполнение", "text": "Демонтаж существующего ПУ, установка нового, подключение цепей учета, проверка работоспособности."}, {"name": "Завершение", "text": "Оформление документации и ввод электроустановки в работу."}]}, {"id": 8, "group": "install", "title": "Установка модема АСКУЭ", "fullTitle": "Установка (замена) модема (устройства передачи данных) для системы АСКУЭ", "sections": [{"name": "Назначение", "text": "Работы предназначены для установки или замены модема передачи данных в системе автоматизированного учета электроэнергии."}, {"name": "Условия выполнения", "text": "Работы выполняются по распоряжению без снятия напряжения, если иное не предусмотрено условиями установки."}, {"name": "Подготовка", "text": "Подготовка модема, SIM-карты, антенны, кабелей связи, инструмента и СИЗ. Проверка зоны покрытия связи."}, {"name": "Выполнение", "text": "Монтаж модема, подключение к интерфейсу ПУ, установка антенны, настройка канала связи."}, {"name": "Завершение", "text": "Проверка связи с сервером сбора данных, оформление результатов."}]}, {"id": 9, "group": "install", "title": "Установка (замена) вводного отключающего устройства", "fullTitle": "Установка (замена) вводного отключающего устройства в электроустановках напряжением до 1000 В", "sections": [{"name": "Назначение", "text": "Работы предназначены для установки или замены вводных отключающих устройств в электроустановках до 1000 В."}, {"name": "Условия выполнения", "text": "Работы выполняются по наряду-допуску со снятием напряжения."}, {"name": "Подготовка", "text": "Подготовка вводного устройства, инструмента, средств защиты и оформление допуска."}, {"name": "Выполнение", "text": "Демонтаж старого устройства, установка нового, подключение проводников и проверка работоспособности."}, {"name": "Завершение", "text": "Ввод устройства в работу и оформление документации."}]}, {"id": 10, "group": "other", "title": "Протяжка контактных соединений ПУ сплит-исполнения", "fullTitle": "Протяжка контактных соединений прибора учета электроэнергии прямого включения сплит-исполнения в электроустановках напряжением до 1000 В", "sections": [{"name": "Назначение", "text": "Работы предназначены для восстановления и обеспечения надежности контактных соединений приборов учета сплит-исполнения."}, {"name": "Условия выполнения", "text": "Работы выполняются по наряду-допуску или распоряжению с отключением линии."}, {"name": "Подготовка", "text": "Обеспечение доступа к прибору учета, подготовка инструмента и средств защиты."}, {"name": "Выполнение", "text": "Отключение, вскрытие контактов, протяжка соединений и контроль их надежности."}, {"name": "Завершение", "text": "Восстановление электроснабжения и оформление результатов."}]}, {"id": 11, "group": "check", "title": "Проверка схемы ПУ сплит-исполнения", "fullTitle": "Проверка схемы включения прибора учета электроэнергии прямого включения сплит-исполнения", "sections": [{"name": "Назначение", "text": "Работы предназначены для проверки корректности схемы подключения ПУ прямого включения сплит-исполнения в электроустановках до 1000 В."}, {"name": "Условия выполнения", "text": "Работы выполняются по распоряжению или в порядке текущей эксплуатации без подъема на высоту. Напряжение не снимается, если иное не требуется."}, {"name": "Подготовка", "text": "Оформление распоряжения, обеспечение инструментом, СИЗ и доступом к измерительному и интерфейсному модулям. Проверка целостности пломб."}, {"name": "Выполнение", "text": "Визуальная проверка схемы подключения, контроль правильности подключения фазных и нулевых проводников, соответствие схемы проектным решениям."}, {"name": "Завершение", "text": "Фиксация результатов проверки, оформление документации."}]}, {"id": 12, "group": "check", "title": "Проверка схемы 1ф ПУ щитового исполнения", "fullTitle": "Проверка схемы учета однофазного прибора учета электроэнергии прямого включения щитового исполнения в электроустановках напряжением до 1000 В", "sections": [{"name": "Назначение", "text": "Работы предназначены для проверки правильности схемы подключения однофазного ПУ в электрощите для подтверждения корректности коммерческого учета."}, {"name": "Условия выполнения", "text": "Работы выполняются по распоряжению или в порядке текущей эксплуатации без подъема на высоту, со снятием напряжения через вводной аппарат."}, {"name": "Подготовка", "text": "Оформление распоряжения, обеспечение доступа к электрощиту, подготовка СИЗ и инструмента. Проверка состояния вводного аппарата и целостности пломб."}, {"name": "Выполнение", "text": "Снятие напряжения, проверка его отсутствия. Визуальная проверка схемы подключения, контроль фазировки и нулевого проводника."}, {"name": "Завершение", "text": "Восстановление напряжения, оформление результатов проверки."}]}, {"id": 13, "group": "check", "title": "Проверка схемы 3ф ПУ щитового исполнения", "fullTitle": "Проверка схемы учета трехфазного прибора учета электроэнергии прямого включения щитового исполнения", "sections": [{"name": "Назначение", "text": "Работы предназначены для проверки схемы подключения трехфазного ПУ прямого включения с использованием эталонного прибора учета."}, {"name": "Условия выполнения", "text": "Работы выполняются по распоряжению, без подъема на высоту, со снятием напряжения через вводной коммутационный аппарат."}, {"name": "Подготовка", "text": "Оформление распоряжения, подготовка эталонного ПУ, инструмента и СИЗ. Обеспечение доступа к электрощиту."}, {"name": "Выполнение", "text": "Снятие напряжения, проверка схемы подключения фаз и нулевого проводника, сравнение показаний с эталонным прибором."}, {"name": "Завершение", "text": "Восстановление электроснабжения, оформление результатов и выводов о состоянии схемы учета."}]}, {"id": 14, "group": "check", "title": "Проверка схемы 3ф ПУ полукосвенного включения", "fullTitle": "Проверка схемы учета трехфазного прибора учета электроэнергии полукосвенного включения щитового исполнения с вводным коммутационным аппаратом", "sections": [{"name": "Назначение", "text": "Работы предназначены для проверки корректности схемы учета трехфазного ПУ полукосвенного включения с применением трансформаторов тока."}, {"name": "Условия выполнения", "text": "Работы выполняются по распоряжению или в порядке текущей эксплуатации, без подъема на высоту. Проверка с использованием токоизмерительных клещей или эталонного ПУ."}, {"name": "Подготовка", "text": "Оформление распоряжения, подготовка измерительных приборов, СИЗ и инструмента. Проверка доступа к ТТ и ПУ."}, {"name": "Выполнение", "text": "Проверка правильности установки и подключения трансформаторов тока, соответствие схемы учета проектным решениям, контроль параметров нагрузки."}, {"name": "Завершение", "text": "Оформление результатов проверки, при необходимости рекомендации по устранению несоответствий."}]}, {"id": 15, "group": "check", "title": "Проверка схемы 3ф ПУ косвенного включения выше 1000 В", "fullTitle": "Проверка схемы учета трехфазного прибора учета электроэнергии косвенного включения щитового исполнения в электроустановках напряжением выше 1000 В", "sections": [{"name": "Назначение", "text": "Работы предназначены для проверки схемы учета трехфазного ПУ косвенного включения в электроустановках напряжением выше 1000 В."}, {"name": "Условия выполнения", "text": "Работы выполняются по распоряжению персоналом СУЭ, без подъема на высоту, в условиях отключенной и заземленной электроустановки."}, {"name": "Подготовка", "text": "Оформление распоряжения, обеспечение отключения и заземления, подготовка СИЗ, инструмента и измерительного оборудования."}, {"name": "Выполнение", "text": "Проверка схемы подключения цепей ТТ и ТН, соответствие вторичных цепей схеме учета, корректность работы ПУ."}, {"name": "Завершение", "text": "Оформление результатов документально, возврат электроустановки в нормальный режим работы."}]}, {"id": 16, "group": "other", "title": "Проверка ПУ в лабораторных условиях", "fullTitle": "Проверка работоспособности прибора учета электроэнергии в лабораторных условиях", "sections": [{"name": "Назначение", "text": "Работы предназначены для проверки исправности и функциональных характеристик ПУ в условиях лаборатории в рамках входного контроля или диагностики."}, {"name": "Условия выполнения", "text": "Работы выполняются в помещении лаборатории по распоряжению, без подъема на высоту, при соблюдении требований к микроклимату."}, {"name": "Подготовка", "text": "Подготовка проверяемого ПУ, лабораторного оборудования, образцового ПУ, программного обеспечения и СИЗ."}, {"name": "Выполнение", "text": "Подключение ПУ к испытательной установке. Проверка корректности измерений, работа интерфейсов связи, реакция на нагрузку, соответствие метрологическим требованиям."}, {"name": "Завершение", "text": "Фиксация результатов, нанесение маркировки или пломбировки, оформление документации по итогам испытаний."}]}, {"id": 17, "group": "other", "title": "Установка (замена) УСПД", "fullTitle": "Установка (замена) устройства сбора и передачи данных (УСПД)", "sections": [{"name": "Назначение", "text": "Работы предназначены для установки или замены УСПД в системе учета электроэнергии с целью обеспечения передачи данных от приборов учета."}, {"name": "Условия выполнения", "text": "Работы выполняются по распоряжению, без подъема на высоту, в условиях достаточной освещенности и нормальных климатических условий."}, {"name": "Подготовка", "text": "Оформление распоряжения, подготовка УСПД, монтажных материалов, инструмента и СИЗ. Обеспечение доступа к месту установки."}, {"name": "Выполнение", "text": "Демонтаж старого УСПД (при наличии), установка нового устройства, подключение питания и линий связи, проверка физического соединения с ПУ."}, {"name": "Завершение", "text": "Пломбировка устройства (при необходимости), оформление результатов установки."}]}, {"id": 18, "group": "other", "title": "Программирование УСПД", "fullTitle": "Программирование (перепрограммирование) устройства сбора и передачи данных (УСПД) в местах установки", "sections": [{"name": "Назначение", "text": "Работы предназначены для настройки параметров УСПД, изменения конфигурации, каналов связи и логики обмена данными с приборами учета."}, {"name": "Условия выполнения", "text": "Работы выполняются по распоряжению, без подъема на высоту, в условиях достаточной освещенности."}, {"name": "Подготовка", "text": "Подготовка программного обеспечения, кабелей связи, СИЗ и доступ к УСПД. Проверка питания устройства."}, {"name": "Выполнение", "text": "Подключение к УСПД, загрузка или изменение конфигурации, проверка корректности обмена данными с ПУ и каналами связи."}, {"name": "Завершение", "text": "Сохранение настроек, фиксация результатов программирования в документации."}]}, {"id": 19, "group": "other", "title": "Контрольный съем показаний ПУ до 1000 В", "fullTitle": "Контрольный съем показаний прибора учета электроэнергии в электроустановках до 1000 В", "sections": [{"name": "Назначение", "text": "Работы предназначены для контрольного съема показаний ПУ в электроустановках до 1000 В с целью сверки данных учета."}, {"name": "Условия выполнения", "text": "Работы выполняются по распоряжению или в порядке текущей эксплуатации, без подъема на высоту и без снятия напряжения."}, {"name": "Подготовка", "text": "Оформление распоряжения, обеспечение доступа к ПУ, подготовка средств фото- или видеофиксации."}, {"name": "Выполнение", "text": "Снятие текущих показаний ПУ, при необходимости выполняется фотофиксация. Проверка целостности пломб."}, {"name": "Завершение", "text": "Показания фиксируются в документации и передаются для дальнейшей обработки."}]}, {"id": 20, "group": "other", "title": "Контрольный съем показаний ПУ выше 1000 В", "fullTitle": "Контрольный съем показаний прибора учета электроэнергии в электроустановках выше 1000 В", "sections": [{"name": "Назначение", "text": "Работы предназначены для контрольного съема показаний ПУ, установленных в электроустановках напряжением выше 1000 В."}, {"name": "Условия выполнения", "text": "Работы выполняются по распоряжению персоналом УРиРУ РЭС или СУЭ, без подъема на высоту и без снятия напряжения."}, {"name": "Подготовка", "text": "Оформление распоряжения, проверка доступа к ПУ, подготовка СИЗ и средств фиксации данных."}, {"name": "Выполнение", "text": "Считывание показаний ПУ, контроль состояния пломб и оборудования."}, {"name": "Завершение", "text": "Результаты съема показаний оформляются установленным порядком."}]}]$seed$::jsonb);
