INSERT INTO riru.docs(category, num, doc_date, name, full_name, code, sort, files) VALUES ('normative', '222', '09.04.2020', 'Порядок компенсации расходов', 'Порядок компенсации со стороны ПАО «Россети Юг» фактических расходов собственника или иного законного владельца объектов электросетевого хозяйства на приобретение электрической энергии в целях компенсации потерь', NULL, 70, $seed$[{"title": "Документ", "ref": "seed:norm-222.pdf", "size": 591510}]$seed$::jsonb);
